import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.NkFLIeLO.js";const b=JSON.parse('{"title":"红果漫剧锐评","description":"只记录真正看完的红果漫剧，一部一段评价，好坏都照实说。","frontmatter":{"title":"红果漫剧锐评","description":"只记录真正看完的红果漫剧，一部一段评价，好坏都照实说。","date":"2026-11-17T00:00:00.000Z","category":"浮生清欢","subCategory":"漫剧锐评","tags":["漫剧","红果","影评"],"author":"闲生"},"headers":[],"relativePath":"posts/life/drama/hongguo-drama-reviews.md","filePath":"posts/life/drama/hongguo-drama-reviews.md"}'),o={name:"posts/life/drama/hongguo-drama-reviews.md"};function s(n,t,l,i,h,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="红果漫剧锐评" tabindex="-1">红果漫剧锐评 <a class="header-anchor" href="#红果漫剧锐评" aria-label="Permalink to &quot;红果漫剧锐评&quot;">​</a></h1><p>短剧图的是下饭和放松，但看得多了，套路一眼就能望到头。这个页面只做一件事：把真正看完的红果漫剧记下来，给个分数，写几句实话。</p><p>不追新，不凑数，没看完的不写。</p><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to &quot;评分标准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>评分</th><th>含义</th></tr></thead><tbody><tr><td>5.0</td><td>值得二刷，会主动推荐给别人</td></tr><tr><td>4.5</td><td>差一点满分，有明显亮点</td></tr><tr><td>4.0</td><td>值得一看，整体不错</td></tr><tr><td>3.0</td><td>中规中矩，打发时间可以</td></tr><tr><td>2.0</td><td>槽点较多，只适合边吐槽边看</td></tr><tr><td>1.0</td><td>不推荐，看完只觉得浪费时间</td></tr></tbody></table><p>评分只看三件事：故事有没有讲完、人物的行为有没有动机、爽点是不是靠降智换来的。制作是否精致排在后面，短剧的成本摆在那里，不苛求。</p><h2 id="收录列表" tabindex="-1">收录列表 <a class="header-anchor" href="#收录列表" aria-label="Permalink to &quot;收录列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>漫剧名称</th><th>评分</th><th>简介</th></tr></thead><tbody><tr><td>万妖图录传</td><td><span style="color:#c9a227;">★★★★★</span> 5.0</td><td>现代少女姜月初魂穿盛唐，得到上古至宝《万妖图录》：以妖血为墨、绘妖入谱，便能夺取对方神通。从虎山神到白蛟龙，她一路斩妖升级，也一步步揭开长安繁华之下的妖魔棋局。</td></tr><tr><td>凡人百世书</td><td><span style="color:#c9a227;">★★★★★</span> 5.0</td><td>陈默身负灭门之仇，濒死时觉醒百世轮回系统，每死一次都能保留意识、积累资质。他化名潜入仇门，游走江湖、军营与朝堂，用一次次失败铺出通往仙途的路。</td></tr><tr><td>聚宝仙盆之杂灵根才是真BOSS</td><td><span style="color:#c9a227;">★★★★</span><span style="background:linear-gradient(90deg,#c9a227 50%,rgba(201,162,39,.25) 50%);-webkit-background-clip:text;background-clip:text;color:transparent;">★</span> 4.5</td><td>杂役弟子贺平生捡到一只破黑盆，能复制万物、提纯资质。别人眼里的废灵根，被他硬生生养成混沌灵根，从此靠脑子和宝盆一路反杀。</td></tr><tr><td>剑神归来：我和驴子的十万年</td><td><span style="color:#c9a227;">★★★★☆</span> 4.0</td><td>陆川被坑货驴系统阿福关在黑暗空间练剑十万年，出关已成老头，剑道无双却时常闪腰。带着一头不靠谱的驴闯修真界，笑点和爽点各占一半。</td></tr><tr><td>我都元婴期了，你跟我说开学</td><td><span style="color:#c9a227;">★★★★☆</span> 4.0</td><td>修士宁尘遭袭重伤，从修真界跌回现代，时间只过了一个暑假，还得去青州大学报到。一边装普通学生，一边寻找资源修复元神，校园日常和修真手段撞出不少笑料。</td></tr></tbody></table><h2 id="关于这个页面" tabindex="-1">关于这个页面 <a class="header-anchor" href="#关于这个页面" aria-label="Permalink to &quot;关于这个页面&quot;">​</a></h2><p>漫剧和短剧的节奏很快，看完容易忘。记下来不是为了给谁看，而是过段时间回头翻，能想起当时为什么愿意一集集点下去。</p><p>如果某部剧的评分和你的观感差得多，那很正常，口味本来就没有标准答案。</p>',11)])])}const u=a(o,[["render",s]]);export{b as __pageData,u as default};
